using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Input;
namespace BluewaterHaul;
public static class CrashRules {
 public static float Mass(string kind)=>kind=="truck"?6500:kind=="bus"?11000:kind=="van"?2600:kind=="pickup"?2200:1400;
 public static Vector2 Bounce(Vector2 velocity,Vector2 normal,float restitution=.25f){float into=Vector2.Dot(velocity,normal);return into<0?velocity-normal*((1+restitution)*into):velocity;}
 public static float Impulse(Vector2 a,Vector2 b,Vector2 normal,float massA,float massB){float closing=Vector2.Dot(a-b,normal);return closing<0?-(1.25f)*closing/(1/massA+1/massB):0;}
}
public sealed class BodyMotion {public Vector2 Velocity;public float Spin,Hold;}
public sealed class Knockdown {public Vector2 Velocity;public float Height,Vertical=3,Time=4;}
public sealed class Blast {public Vector2 Point;public float Time=2;}
public sealed partial class SarniaGame {
 readonly Dictionary<int,BodyMotion> bodyMotion=[];readonly Dictionary<int,Knockdown> knockdowns=[];readonly List<Blast> blasts=[];Vector2 walkingVelocity;float avatarYaw,walkPhase,frameDt=1f/60;
 void WalkPlayer(KeyboardState keys,float dt){var f=VehiclePhysics.Forward(yaw);var r=new Vector2(-f.Y,f.X);Vector2 input=f*((keys.IsKeyDown(Keys.W)?1:0)-(keys.IsKeyDown(Keys.S)?1:0))+r*((keys.IsKeyDown(Keys.D)?1:0)-(keys.IsKeyDown(Keys.A)?1:0));if(input.LengthSquared()>0)input.Normalize();var desired=input*(keys.IsKeyDown(Keys.LeftShift)?5:2.7f);walkingVelocity=Vector2.Lerp(walkingVelocity,desired,1-MathF.Exp(-dt*(input==Vector2.Zero?16:10)));if(walkingVelocity.LengthSquared()<.001f)walkingVelocity=Vector2.Zero;int count=Math.Max(1,(int)MathF.Ceiling(walkingVelocity.Length()*dt/.15f));for(int i=0;i<count;i++){var step=walkingVelocity*dt/count;var x=position+new Vector2(step.X,0);if(!Blocked(x)&&!PedestrianVehicleBlocked(x))position=x;else walkingVelocity.X=0;var z=position+new Vector2(0,step.Y);if(!Blocked(z)&&!PedestrianVehicleBlocked(z))position=z;else walkingVelocity.Y=0;}if(walkingVelocity.LengthSquared()>.04f){float facing=MathF.Atan2(-walkingVelocity.X,-walkingVelocity.Y);avatarYaw+=MathHelper.WrapAngle(facing-avatarYaw)*(1-MathF.Exp(-dt*14));walkPhase+=walkingVelocity.Length()*dt*2.5f;}}
 BodyMotion Motion(int id){if(!bodyMotion.TryGetValue(id,out var b))bodyMotion[id]=b=new();return b;}
 float ResolveCrash(Vector2 q,float heading,float scalar){var active=ActiveVehicle;var velocity=VehiclePhysics.Forward(heading)*scalar;var spec=ActiveSpec;Vector2 normal=-Vector2.Normalize(velocity);float otherMass=0;Vector2 otherVelocity=default;Action<Vector2>? shove=null;
  foreach(var v in fleet.Where(v=>v.Id!=active.Id)){if(!VehiclePhysics.Overlap(q,heading,spec,v.Point,v.Yaw,VehicleSpec.For(v.Kind)))continue;normal=ContactNormal(position,v.Point,velocity);otherMass=CrashRules.Mass(v.Kind);otherVelocity=Motion(v.Id).Velocity;shove=impulse=>{var b=Motion(v.Id);b.Velocity+=impulse; b.Spin+=Vector2.Dot(impulse,new Vector2(-normal.Y,normal.X))*.08f;v.Damage=Math.Clamp(v.Damage+TroubleRules.Damage(scalar)*.7f,0,100);};break;}
  if(shove==null)foreach(var t in traffic){if(!VehiclePhysics.Overlap(q,heading,spec,t.Point,t.Yaw,VehicleSpec.For(t.Kind)))continue;normal=ContactNormal(position,t.Point,velocity);otherMass=CrashRules.Mass(t.Kind);otherVelocity=VehiclePhysics.Forward(t.Yaw)*t.Speed;shove=impulse=>{var b=Motion(-10000-t.Id);b.Velocity=otherVelocity+impulse;b.Hold=3;t.Speed=0;t.Damage=Math.Clamp(t.Damage+TroubleRules.Damage(scalar),0,100);};break;}
  if(shove==null)foreach(var p in police){if(!VehiclePhysics.Overlap(q,heading,spec,p.Point,p.Yaw,VehicleSpec.For("car")))continue;normal=ContactNormal(position,p.Point,velocity);otherMass=1400;shove=impulse=>{var b=Motion(-20000-p.Id);b.Velocity+=impulse;b.Hold=2;};break;}
  bool hitPerson=false;foreach(var c in citizens){var d=c.Point-q;var f=VehiclePhysics.Forward(heading);var r=new Vector2(-f.Y,f.X);if(Math.Abs(Vector2.Dot(d,f))>spec.Length/2+.6f||Math.Abs(Vector2.Dot(d,r))>spec.Width/2+.6f)continue;hitPerson=true;knockdowns[c.Id]=new(){Velocity=velocity*.65f,Vertical=Math.Clamp(Math.Abs(scalar)*.2f,2,6)};}
  if(shove==null){float nearest=100;foreach(var b in world.Buildings.Where(b=>Vector2.DistanceSquared(Geo.V(b.Center),q)<10000))for(int i=0;i<b.Points.Count;i++){var edge=Geo.Nearest(q,Geo.V(b.Points[i]),Geo.V(b.Points[(i+1)%b.Points.Count]));float d=Vector2.DistanceSquared(edge,q);if(d<nearest){nearest=d;normal=ContactNormal(position,edge,velocity);}}}
  Impact(q,heading,scalar);if(shove!=null){float impulse=CrashRules.Impulse(velocity,otherVelocity,normal,CrashRules.Mass(active.Kind),otherMass);velocity+=normal*(impulse/CrashRules.Mass(active.Kind));shove(-normal*(impulse/otherMass));}else velocity=hitPerson?velocity*.85f:CrashRules.Bounce(velocity,normal);var fwd=VehiclePhysics.Forward(heading);float result=Vector2.Dot(velocity,fwd);Motion(active.Id).Velocity+=velocity-fwd*result;Motion(active.Id).Spin+=MathHelper.WrapAngle(MathF.Atan2(-normal.X,-normal.Y)-heading)*Math.Min(1,Math.Abs(scalar)*.025f);return Math.Clamp(result,-8,12);
 }
 static Vector2 ContactNormal(Vector2 a,Vector2 b,Vector2 velocity){var n=a-b;if(n.LengthSquared()<.001f)return -Vector2.Normalize(velocity);n.Normalize();if(Vector2.Dot(n,velocity)>0)n=-n;return n;}
 bool OutdoorBlocked(Vector2 p){long saved=interior;interior=0;try{return Blocked(p);}finally{interior=saved;}}
 bool StaticBodyBlocked(Vector2 q,float heading,VehicleSpec spec){if(VehiclePhysics.Outline(q,heading,spec,.12f).Any(OutdoorBlocked))return true;var f=VehiclePhysics.Forward(heading);var r=new Vector2(-f.Y,f.X);for(float z=-spec.Length/2;z<=spec.Length/2;z+=.8f)for(int side=-1;side<=1;side++)if(OutdoorBlocked(q+f*z+r*(spec.Width/2)*side))return true;return false;}
 void MoveBody(ref Vector2 point,ref float heading,BodyMotion motion,VehicleSpec spec,float dt){int steps=Math.Max(1,(int)MathF.Ceiling(motion.Velocity.Length()*dt/.2f));for(int i=0;i<steps;i++){var step=motion.Velocity*dt/steps;var q=point+step;float rotation=heading+motion.Spin*dt/steps;if(!StaticBodyBlocked(q,rotation,spec)){point=q;heading=rotation;}else{var x=point+new Vector2(step.X,0);var z=point+new Vector2(0,step.Y);if(!StaticBodyBlocked(x,heading,spec))point=x;else motion.Velocity.X*= -.22f;if(!StaticBodyBlocked(z,heading,spec))point=z;else motion.Velocity.Y*= -.22f;motion.Spin*= -.3f;}}motion.Velocity*=MathF.Exp(-dt*2);motion.Spin*=MathF.Exp(-dt*3);motion.Hold=Math.Max(0,motion.Hold-dt);}
 void UpdateCrashPhysics(float dt){foreach(var v in fleet){if(bodyMotion.TryGetValue(v.Id,out var body)){var p=v.Point;var h=v.Yaw;MoveBody(ref p,ref h,body,VehicleSpec.For(v.Kind),dt);v.Point=p;v.Yaw=h;if(driving&&activeVehicle==v.Id){position=p;yaw=h;}if(v.Id==0){truck=p;state.TruckYaw=h;}}if(v.Destroyed)continue;if(v.Damage>=85){v.BurnTime+=dt;v.Damage=Math.Min(100,v.Damage+dt*1.5f);}if(v.Damage>=100||v.BurnTime>=8)Explode(v);}
  foreach(var t in traffic){if(bodyMotion.TryGetValue(-10000-t.Id,out var body)){MoveBody(ref t.Point,ref t.Yaw,body,VehicleSpec.For(t.Kind),dt);var a=carRouter.Nodes[t.Link.From];var b=carRouter.Nodes[t.Link.To];t.Distance=Math.Clamp(Vector2.Dot(t.Point-a,Vector2.Normalize(b-a)),0,Vector2.Distance(a,b));}if(t.Damage>=85&&!t.Destroyed){t.BurnTime+=dt;if(t.BurnTime>8){t.Destroyed=true;blasts.Add(new(){Point=t.Point});}}}
  foreach(var p in police)if(bodyMotion.TryGetValue(-20000-p.Id,out var body))MoveBody(ref p.Point,ref p.Yaw,body,VehicleSpec.For("car"),dt);
  foreach(var pair in knockdowns.ToArray()){var c=citizens.FirstOrDefault(c=>c.Id==pair.Key);if(c==null){knockdowns.Remove(pair.Key);continue;}var k=pair.Value;var q=c.Point+k.Velocity*dt;if(!OutdoorBlocked(q))c.Point=q;else k.Velocity*= -.2f;k.Velocity*=MathF.Exp(-dt*1.8f);k.Height=Math.Max(0,k.Height+k.Vertical*dt);k.Vertical-=9.8f*dt;if(k.Height==0)k.Vertical=0;k.Time-=dt;if(k.Time<=0){knockdowns.Remove(pair.Key);c.Activity="";}}
  foreach(var blast in blasts)blast.Time-=dt;blasts.RemoveAll(b=>b.Time<=0);
 }
 void Explode(VehicleState v){if(v.Destroyed)return;v.Destroyed=true;v.Fuel=0;v.Damage=100;blasts.Add(new(){Point=v.Point});if(v.Id==0)state.Fuel=0;foreach(var other in fleet.Where(w=>w!=v&&Vector2.DistanceSquared(w.Point,v.Point)<15*15)){var delta=other.Point-v.Point;float distance=Math.Max(1,delta.Length());Motion(other.Id).Velocity+=delta/distance*(15-distance);other.Damage=Math.Min(100,other.Damage+(15-distance)*3);}
  foreach(var c in citizens.Where(c=>Vector2.DistanceSquared(c.Point,v.Point)<12*12)){var delta=c.Point-v.Point;knockdowns[c.Id]=new(){Velocity=delta.LengthSquared()>.01f?Vector2.Normalize(delta)*8:Vector2.UnitX*8,Vertical=4};}
  if(driving&&activeVehicle==v.Id){speed=0;if(!ExitVehicle()){driving=false;position=SidewalkPoint(v.Point+new Vector2(8,8));}cameraReady=false;walkingVelocity=Vector2.Zero;}Crime("Property damage",v.Point,35);Tell("Vehicle exploded. Wreck remains; K repairs it at a fuel/repair stop.");}
 void DrawCrashEffects(MeshBuilder m){foreach(var pair in knockdowns){var c=citizens.FirstOrDefault(c=>c.Id==pair.Key);if(c==null||Vector2.DistanceSquared(c.Point,position)>300*300)continue;float y=GroundHeight(c.Point)+pair.Value.Height;m.Box(new(c.Point.X-.65f,y+.1f,c.Point.Y-.2f),new(c.Point.X+.4f,y+.4f,c.Point.Y+.2f),new(73,85,112));m.Box(new(c.Point.X+.4f,y+.12f,c.Point.Y-.16f),new(c.Point.X+.7f,y+.43f,c.Point.Y+.16f),new(207,164,126));}foreach(var v in fleet.Where(v=>v.Damage>=85&&!v.Destroyed&&Vector2.DistanceSquared(v.Point,position)<400*400)){float y=GroundHeight(v.Point);m.Box(Geo.V3(v.Point-new Vector2(.55f),y+1),Geo.V3(v.Point+new Vector2(.55f),y+2.7f),new(245,112,30));m.Box(Geo.V3(v.Point-new Vector2(.4f),y+2.7f),Geo.V3(v.Point+new Vector2(.4f),y+4.5f),new(75,72,69));}foreach(var blast in blasts){float radius=(2-blast.Time)*4+.6f;float y=GroundHeight(blast.Point);m.Box(Geo.V3(blast.Point-new Vector2(radius),y+.2f),Geo.V3(blast.Point+new Vector2(radius),y+radius*1.8f),blast.Time>1?new(252,167,45):new(88,79,66));}}
 void PhysicsSmoke(){var v=fleet.First(w=>w.Kind=="car"&&!w.Destroyed);var other=fleet.First(w=>w.Kind=="car"&&w.Id!=v.Id&&!w.Destroyed);var lane=citySpawnLinks.First(l=>Vector2.Distance(carRouter.Nodes[l.From],carRouter.Nodes[l.To])>60&&!StaticBodyBlocked(CityPoint(l,20),LinkYaw(l),VehicleSpec.For("car"))&&!StaticBodyBlocked(CityPoint(l,25),LinkYaw(l),VehicleSpec.For("car")));position=CityPoint(lane,20);yaw=LinkYaw(lane);activeVehicle=v.Id;driving=true;v.Point=position;v.Yaw=yaw;other.Point=position+VehiclePhysics.Forward(yaw)*4.8f;other.Yaw=yaw;var parked=other.Point;ResolveCrash(position+VehiclePhysics.Forward(yaw)*.5f,yaw,12);UpdateCrashPhysics(.1f);if(Vector2.Distance(parked,other.Point)<.05f)throw new InvalidDataException("Hit car did not move");var citizen=citizens[0];citizen.Point=position+VehiclePhysics.Forward(yaw)*2;ResolveCrash(position+VehiclePhysics.Forward(yaw)*.2f,yaw,10);if(!knockdowns.ContainsKey(citizen.Id))throw new InvalidDataException("Pedestrian knockdown failed");driving=false;v.Damage=90;float before=v.Damage;UpdateCrashPhysics(.5f);if(v.Damage<=before||v.BurnTime<=0)throw new InvalidDataException("Fire progression failed");v.Damage=100;UpdateCrashPhysics(.1f);if(!v.Destroyed||!blasts.Any())throw new InvalidDataException("Explosion failed");Save();LoadSave();if(!fleet.First(w=>w.Id==v.Id).Destroyed)throw new InvalidDataException("Wreck persistence failed");thirdPerson=true;position=SidewalkPoint(v.Point+new Vector2(8,8));yaw=MathF.Atan2(-(v.Point-position).X,-(v.Point-position).Y);cameraReady=false;blasts.Add(new(){Point=v.Point});Capture("crash-explosion");Console.WriteLine("PASS crash: damage progression, explosion, wreck persistence and render.");}
